import { z } from 'zod';
import type {
  ProfileReferenceInput,
  ProfileCollectionProgress,
} from '../../types/design-profile';

export interface BoardPage {
  remoteId: string;
  title: string;
  references: ProfileReferenceInput[];
  cursor: string | null;
  isComplete: boolean;
  total?: number;
  collection?: ProfileCollectionProgress;
}
const optionalText = z.string().nullable().optional();
const pin = z.object({
  id: z.string().min(1),
  image_urls: z.array(z.string().url()),
  title: optionalText,
  description: optionalText,
  alt_text: optionalText,
});
const block = z.object({
  id: z.string().min(1),
  kind: z.enum(['block', 'channel']),
  block_type: optionalText,
  title: optionalText,
  description: optionalText,
  content: optionalText,
  image_urls: z.array(z.string().url()),
  attachment_url: optionalText,
});
const pinterestResponse = z.discriminatedUnion('type', [
  z.object({
    status: z.literal('ok'),
    type: z.literal('pin'),
    pins: z.tuple([pin]),
  }),
  z.object({
    status: z.literal('ok'),
    type: z.literal('board'),
    board: z.object({ id: z.string().min(1), name: optionalText }),
    pins: z.array(pin),
    page: z.object({
      nextCursor: z.string().min(1).nullable(),
      isComplete: z.boolean(),
    }),
  }),
]);
const arenaResponse = z.discriminatedUnion('type', [
  z.object({
    status: z.literal('ok'),
    type: z.literal('block'),
    contents: z.tuple([block.extend({ kind: z.literal('block') })]),
  }),
  z.object({
    status: z.literal('ok'),
    type: z.literal('channel'),
    channel: z.object({ id: z.string().min(1), title: optionalText }),
    contents: z.array(block),
    meta: z.object({
      current_page: z.number().int().positive(),
      total_pages: z.number().int().nonnegative(),
      total_count: z.number().int().nonnegative().nullable().optional(),
      has_more_pages: z.boolean(),
    }),
  }),
]);

const pinReference = (item: z.infer<typeof pin>): ProfileReferenceInput => ({
  provider: 'pinterest',
  remoteId: item.id,
  title: item.title ?? 'Pinterest reference',
  text: [item.description, item.alt_text].filter(Boolean).join('\n'),
  media: [],
  remoteImages: item.image_urls.length
    ? [item.image_urls[item.image_urls.length - 1]]
    : [],
  url: `https://www.pinterest.com/pin/${item.id}/`,
});

const arenaReference = (
  item: z.infer<typeof block>,
): ProfileReferenceInput => ({
  provider: 'arena',
  remoteId: item.kind === 'channel' ? `channel:${item.id}` : item.id,
  title: item.title ?? 'Are.na reference',
  text: [item.content, item.description].filter(Boolean).join('\n'),
  media: [],
  remoteImages: item.image_urls.length ? [item.image_urls[0]] : [],
  url: `https://www.are.na/${item.kind === 'channel' ? 'channel' : 'block'}/${item.id}`,
  ...(item.kind === 'channel'
    ? {
        unsupportedReason:
          'Nested channel; connect it separately to import its contents',
      }
    : {}),
  ...(item.kind !== 'channel' && !item.image_urls.length && !item.content
    ? {
        unsupportedReason: item.attachment_url
          ? 'Attachment requires a supported document import'
          : 'No supported image or text representation',
      }
    : {}),
});

export const pinterestPage = (
  input: unknown,
  cursor: string | null,
): BoardPage => {
  const parsed = pinterestResponse.safeParse(input);
  if (!parsed.success)
    throw new Error(
      'Pinterest must return one complete pin or a board with complete pagination metadata. The Rivet proxy must support board paging; public boards may be blocked by provider access.',
    );
  const data = parsed.data;
  if (data.type === 'pin') {
    if (cursor !== null)
      throw new Error('Pinterest returned a pin during board continuation');
    const reference = pinReference(data.pins[0]);
    return {
      remoteId: `pin:${reference.remoteId}`,
      title: reference.title,
      references: [reference],
      cursor: null,
      isComplete: true,
      total: 1,
    };
  }
  if (data.page.nextCursor === cursor && !data.page.isComplete)
    throw new Error('Pinterest returned a repeated page cursor');
  if (data.page.isComplete !== (data.page.nextCursor === null))
    throw new Error(
      'Pinterest pagination returned inconsistent exhaustion metadata',
    );
  return {
    remoteId: data.board.id,
    title: data.board.name ?? 'Pinterest board',
    cursor: data.page.nextCursor,
    isComplete: data.page.isComplete,
    references: data.pins.map(pinReference),
  };
};

export const arenaPage = (input: unknown, cursor: string | null): BoardPage => {
  const data = arenaResponse.parse(input);
  if (data.type === 'block') {
    if (cursor !== null)
      throw new Error('Are.na returned a block during channel continuation');
    const reference = arenaReference(data.contents[0]);
    return {
      remoteId: `block:${reference.remoteId}`,
      title: reference.title,
      references: [reference],
      cursor: null,
      isComplete: true,
      total: 1,
    };
  }
  const page = Number(cursor ?? 1);
  if (data.meta.current_page !== page)
    throw new Error(
      'Are.na returned a different page; the Rivet proxy must support channel paging',
    );
  const isComplete = !data.meta.has_more_pages;
  if (
    data.meta.has_more_pages !== page < data.meta.total_pages ||
    page > Math.max(1, data.meta.total_pages)
  )
    throw new Error(
      'Are.na pagination returned inconsistent exhaustion metadata',
    );
  return {
    remoteId: data.channel.id,
    title: data.channel.title ?? 'Are.na channel',
    cursor: isComplete ? null : String(page + 1),
    isComplete,
    ...(data.meta.total_count !== null && data.meta.total_count !== undefined
      ? { total: data.meta.total_count }
      : {}),
    references: data.contents.map(arenaReference),
  };
};
